brute_force_solution:
import itertools
def findMinArrowShots(points):
    if not points:
        return 0
    cands = sorted({x for p in points for x in p})
    for k in range(1, len(points) + 1):
        for comb in itertools.combinations(cands, min(k, len(cands))):
            if all(any(s <= x <= e for x in comb) for s, e in points):
                return k
    return len(points)

